# =============================================================================
# SCRIPT 03: FIGURES - POLYNOMIAL ORDER (nu = 0, 2, 5) AND FIXED m
# =============================================================================
# Paper: Prass, T. S. and Pumi, G. (2021). On the behavior of the DFA and DCCA
#        in trend-stationary processes. Journal of Multivariate Analysis,
#        182, 104703.
#
# Reads the simulation outputs from `results/part1_nu_mfixed/` (generated by
# Script 02) and produces:
#   - figures/figNu025.pdf (Figure 4 in the main manuscript: boxplots of
#                           F^2_{1,DFA}, F^2_{2,DFA}, F_DCCA, and rho_DCCA for
#                           nu in {0, 2, 5} and pairwise differences between
#                           nu = 2 and nu = 5)
#   - figures/c1mfixed.pdf (Figure S2(a) in the Supplementary Material:
#                           rho_DCCA(100) vs. n for two i.i.d. sequences)
#   - figures/c2mfixed.pdf (Figure S2(b) in the Supplementary Material:
#                           rho_DCCA(100) vs. n for independent AR(1) and MA(1))
# =============================================================================

library(ggplot2)
library(ggpubr)

indir  <- "results/part1_nu_mfixed"
outdir <- "figures"
dir.create(outdir, showWarnings = FALSE)

My_theme <- theme_bw() +
  theme(
    text = element_text(size = rel(4), face = "bold"),
    strip.text.x = element_text(size = rel(4)),
    strip.text.y = element_text(size = rel(4))
  )

# =============================================================================
# 1. Effect of polynomial order nu in {0, 2, 5} (Figure 4)
# =============================================================================
ms    <- seq(1000, 1100, 10)
nus   <- c(0, 2, 5)
cores <- c("blue", "red", "green", "yellow")
final <- "_1_2.txt"

read_sim_stack <- function(prefix) {
  df <- read.table(file.path(indir, paste0(prefix, final)), header = FALSE)
  colnames(df) <- ms
  stack(df)
}

plot_nu_box <- function(df, y_expr, fill_col) {
  ggplot() +
    xlab("m") + ylab(y_expr) +
    geom_boxplot(data = df, aes(x = as.factor(ind), y = values),
                 fill = fill_col, alpha = 0.2) +
    My_theme
}

# Build one row of 4 panels (nu = 0, nu = 2, nu = 5, and difference nu = 2 minus nu = 5)
build_stat_row <- function(stat_prefix, label_fn, fill_col) {
  dfs <- lapply(0:2, function(k) read_sim_stack(paste0(stat_prefix, k)))
  plots_nu <- lapply(seq_along(nus), function(k) {
    plot_nu_box(dfs[[k]], label_fn(nus[k]), fill_col)
  })
  dif_df <- data.frame(values = dfs[[2]]$values - dfs[[3]]$values, ind = dfs[[2]]$ind)
  plot_dif <- plot_nu_box(dif_df, "", "grey")
  c(plots_nu, list(plot_dif))
}

row1 <- build_stat_row("dfa1",    function(nu_val) bquote({F["1,DFA"]^2}(m) ~ " with " ~ nu == .(nu_val)), cores[1])
row2 <- build_stat_row("dfa2",    function(nu_val) bquote({F["2,DFA"]^2}(m) ~ " with " ~ nu == .(nu_val)), cores[2])
row3 <- build_stat_row("dcca",    function(nu_val) bquote({F[DCCA]}(m)      ~ " with " ~ nu == .(nu_val)), cores[3])
row4 <- build_stat_row("rhodcca", function(nu_val) bquote({rho[DCCA]}(m)    ~ " with " ~ nu == .(nu_val)), cores[4])

pdf(file.path(outdir, "figNu025.pdf"), width = 20, height = 10)
print(ggarrange(plotlist = c(row1, row2, row3, row4), ncol = 4, nrow = 4))
dev.off()

# =============================================================================
# 2. Fixed window size m = 100, varying sample size n (Figure S2)
# =============================================================================
ns <- seq(500, 10000, 100)

plot_mfixed <- function(infile, outfile) {
  df <- read.table(file.path(indir, infile), header = FALSE)
  colnames(df) <- ns
  pdf(file = file.path(outdir, outfile), width = 10, height = 6)
  boxplot(df, ylab = expression(rho[DCCA](100)), xlab = "n", cex = 0.5)
  box()
  abline(h = 0, col = "red", lwd = 2)
  dev.off()
}

plot_mfixed("mfixed1.txt", "c1mfixed.pdf")
plot_mfixed("mfixed2.txt", "c2mfixed.pdf")
